{
  "name": "键盘仿真读取器",
  "name_en": "Keyboard-like Reader",
  "manufacturer": "",
  "description": "一个非物理的软件读取组件，用于与键盘仿真式输入源配合，读取原始数据、按块解析内容，并将输入转换为有意义的按键或文本数据。可用于实验中接收扫码器、读码器或其他以键盘输入方式输出的数据流。",
  "description_en": "A non-physical software reading component for use with keyboard-emulating input sources. It reads raw data, parses chunked content, and converts the input into meaningful key or text data. It can be used in laboratory workflows to receive data streams from scanners, code readers, or other devices that output as keyboard input.",
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化读取组件，准备接收键盘仿真输入数据。",
      "description_en": "Initialize the reader component and prepare it to receive keyboard-emulated input data."
    },
    {
      "action_name": "auto-read",
      "description": "读取一次原始输入数据。",
      "description_en": "Read one set of raw input data."
    },
    {
      "action_name": "auto-decode_raw_data",
      "description": "解码原始数据内容。",
      "description_en": "Decode the raw data content."
    },
    {
      "action_name": "auto-extract_meaningful_data_from_chunk",
      "description": "从数据块中提取有意义的数据。",
      "description_en": "Extract meaningful data from a chunk of input data."
    },
    {
      "action_name": "auto-get_chunked_data",
      "description": "将原始数据拆分为数据块。",
      "description_en": "Split raw data into chunks."
    },
    {
      "action_name": "auto-raw_data_to_keys",
      "description": "将原始数据转换为按键或字符序列。",
      "description_en": "Convert raw data into key or character sequences."
    }
  ],
  "tag_hints": [
    "keyboard emulation",
    "input decoding",
    "scanner data parsing",
    "raw data parsing",
    "HID-like input",
    "text extraction"
  ]
}

